from html.parser import HTMLParser
from pathlib import Path
import hashlib, json, re
class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.text = []
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1
    def handle_endtag(self, tag):
        if tag in {'script', 'style'}:
            self.hidden = max(0, self.hidden - 1)
    def handle_data(self, data):
        if not self.hidden and data.strip():
            self.text.append(' '.join(data.split()))
root = Path('products/services/catalogue-qa-digital-checkout')
raw = (root / 'raw/store-activation.html').read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == 'd102facab7ecb1ca3cc58210b05f84d69618639d8289bab66c08b034873fc7a4'
page = Page()
page.feed(raw.decode('utf-8'))
pattern = re.compile(r'verif|identity|approv|review|activat|business|payout|test mode|restrict|marketplace', re.I)
indices = [i for i, text in enumerate(page.text) if pattern.search(text)]
selected = sorted({j for i in indices for j in range(max(0, i-2), min(len(page.text), i+3))})
result = {'source': 'https://docs.lemonsqueezy.com/help/getting-started/activate-your-store', 'fetch_receipt': 'TASK-179498880200', 'sha256': digest, 'scope': 'Visible HTML text candidates for manual verification against the official page. This is not evidence of seller or Marketplace approval.', 'excerpts': [{'index': i, 'text': page.text[i]} for i in selected]}
out = root / 'store-activation-extract.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'excerpt_count': len(json.loads(out.read_text(encoding='utf-8'))['excerpts'])}))
